Definition fzH1a_post (gp tp s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P regb cfgb schedb v q va i lo : Z) (LB : list block) (m : mem) : machine_state -> Prop :=
  fun ms' => exists ra t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra (Z_to_bv 64 P) gp tp t0 t1 t2 (Z_to_bv 64 regb) (Z_to_bv 64 0)
                  a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_FZ_PASS2) fc None m' (seg_rom rsegs)
    /\ munch [(lo, P); (q + 32, q + 72); (schedb, schedb + SZ_SCH)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo P
    /\ StreamSvc LB m' v (ssvc_hdr (P + 384) schedb) q
    /\ ImplBlock LB m' q (mkIMPL (mkSPC VP_SPCI_IMPL 1 1 i) 0 va [] 1)
    /\ Scheduler LB m' schedb (mkSCH (sched_hdr (P + 384) cfgb) 0 0 1).

Definition fzH1b_post (gp tp s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P regb cfgb schedb v q va i lo : Z) (LB : list block) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR (Z_to_bv 64 P_FZ_RET_DSV) (Z_to_bv 64 P) gp tp t0 t1 t2 (Z_to_bv 64 regb) (Z_to_bv 64 schedb)
                  (Z_to_bv 64 v) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_DESTROY_ALLOC_SSVC) fc None m' (seg_rom rsegs)
    /\ munch [(lo, P); (q + 32, q + 72); (schedb, schedb + SZ_SCH)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo P
    /\ StreamSvc LB m' v (ssvc_hdr (P + 384) schedb) q
    /\ ImplBlock LB m' q (mkIMPL (mkSPC VP_SPCI_IMPL 1 1 i) 0 va [] 1)
    /\ Scheduler LB m' schedb (mkSCH (sched_hdr (P + 384) cfgb) 0 0 1).

Definition fzH1_hyps (m : mem) (P allocb regb cfgb schedb v q va i lo : Z) (LB : list block) (shut : Z) : Prop :=
  rw_cells rsegs m (P + 384) (IoCtxCells allocb regb schedb)
  /\ Registry LB m regb (P + 384) v 0 /\ regb + NEWSZ_REG <= hceil
  /\ StreamSvc LB m v (ssvc_hdr (P + 384) schedb) q /\ 0 < v /\ v mod 8 = 0 /\ v + NEWSZ_SSVC <= hceil
  /\ ImplBlock LB m q (mkIMPL (mkSPC VP_SPCI_IMPL 1 1 i) 0 va [] 1)
  /\ Scheduler LB m schedb (mkSCH (sched_hdr (P + 384) cfgb) 0 0 shut) /\ 0 < schedb /\ schedb mod 16 = 0 /\ schedb + NEWSZ_SCH <= hceil
  /\ (schedb + NEWSZ_SCH <= 0x10000 \/ 0xb4000 <= schedb)
  /\ ConfigSvc LB m cfgb (cfg_hdr (P + 384)) /\ 0 < cfgb /\ cfgb + NEWSZ_CFG <= hceil
  /\ (v + NEWSZ_SSVC <= q \/ q + SZ_SPCI_IMPL <= v) /\ (va + 8 <= q \/ q + SZ_SPCI_IMPL <= va)
  /\ (regb + NEWSZ_REG <= q \/ q + SZ_SPCI_IMPL <= regb) /\ (regb + NEWSZ_REG <= schedb \/ schedb + NEWSZ_SCH <= regb)
  /\ (v + NEWSZ_SSVC <= schedb \/ schedb + NEWSZ_SCH <= v) /\ (cfgb + NEWSZ_CFG <= q \/ q + SZ_SPCI_IMPL <= cfgb)
  /\ (cfgb + NEWSZ_CFG <= schedb \/ schedb + NEWSZ_SCH <= cfgb) /\ (q + SZ_SPCI_IMPL <= schedb \/ schedb + NEWSZ_SCH <= q)
  /\ (va + 8 <= schedb \/ schedb + NEWSZ_SCH <= va)
  /\ XStatics m
  /\ stk rsegs m lo P /\ lo + FZ_H1_STACK <= P /\ hceil <= lo /\ P mod 16 = 0 /\ P + 512 < 2^64
  /\ mem_inv rsegs m.

