(* [comment removed for export] *)
Lemma Registry_open : forall LB m r owner first lk,
  Registry LB m r owner first lk ->
  exists p j0 j7, In (p, r, NEWSZ_REG) LB
    /\ rw_cells rsegs m r [CB 8 j0]
    /\ rw_cells rsegs m (r + 8) [CB 4 [b8 0; b8 0; b8 0; b8 0]; C4 (wz lk);
                      CB 32 [b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0;
                             b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0]]
    /\ (lk = 0 \/ lk = EBUSY) /\ (r + 8) mod 4 = 0
    /\ rw_cells rsegs m (r + 48) [C8 (wz owner); C8 (wz first)]
    /\ rw_cells rsegs m (r + 64) (CookieCells j7).
Proof.
  intros LB m r owner first lk (p & j0 & j7 & IN & R0 & PM & ROF & RCK). exists p, j0, j7.
  unfold O_REG_MUTEX, O_REG_OWNER, SZ_REG in *. destruct (PMutex_cells _ _ _ PM) as (PMC & LK & AL).
  repeat (split; [fast_assumption|]). exact RCK.
Qed.

Lemma Registry_close : forall LB m r owner first lk p j0 j7,
  In (p, r, NEWSZ_REG) LB ->
  rw_cells rsegs m r [CB 8 j0] ->
  rw_cells rsegs m (r + 8) [CB 4 [b8 0; b8 0; b8 0; b8 0]; C4 (wz lk);
                      CB 32 [b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0;
                             b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0]] ->
  (lk = 0 \/ lk = EBUSY) -> (r + 8) mod 4 = 0 ->
  rw_cells rsegs m (r + 48) [C8 (wz owner); C8 (wz first)] ->
  rw_cells rsegs m (r + 64) (CookieCells j7) ->
  Registry LB m r owner first lk.
Proof.
  intros LB m r owner first lk p j0 j7 IN R0 PMC LK AL ROF RCK. exists p, j0, j7.
  unfold O_REG_MUTEX, O_REG_OWNER, SZ_REG. split; [exact IN|]. split; [exact R0|]. split; [apply PMutex_fold; fast_assumption|]. split; fast_assumption.
Qed.

(* [comment removed for export] *)
Definition fzH2_post (gp tp s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P regb cfgb schedb : Z) (LB : list block) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR (Z_to_bv 64 P_FZ_RET_DSV) (Z_to_bv 64 P) gp tp t0 t1 t2 (Z_to_bv 64 regb) (Z_to_bv 64 cfgb)
                  (Z_to_bv 64 schedb) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_DESTROY_ALLOC_SCHED) fc None m' (seg_rom rsegs)
    /\ munch [(regb + 56, regb + 64)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ Registry LB m' regb (P + 384) schedb 0.

Lemma fzH2 : forall gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P regb cfgb schedb fst0 : Z) (LB : list block) (sst ssh : Z),
  Registry LB m regb (P + 384) fst0 0 -> regb + NEWSZ_REG <= hceil ->
  Scheduler LB m schedb (mkSCH (sched_hdr (P + 384) cfgb) 0 sst ssh) -> 0 < schedb -> schedb + NEWSZ_SCH <= hceil ->
  (regb + NEWSZ_REG <= schedb \/ schedb + NEWSZ_SCH <= regb) ->
  mem_inv rsegs m ->
  evt rsegs (fzH2_post gp tp s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P regb cfgb schedb LB m)
    (MS (mkR (Z_to_bv 64 P_FZ_RET_DSV) (Z_to_bv 64 P) gp tp t0 t1 t2 (Z_to_bv 64 regb) (Z_to_bv 64 schedb) a0 a1 a2 a3 a4 a5 a6 a7
             s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_FZ_RET_DSV) fc None m (seg_rom rsegs)).
