(* [comment removed for export] *)
Definition fzH4_post (gp tp s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P allocb regb : Z) (LB : list block) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR (Z_to_bv 64 P_FZ_RET_DRG) (Z_to_bv 64 P) gp tp t0 t1 t2 (Z_to_bv 64 regb) s1
                  (Z_to_bv 64 P) (Z_to_bv 64 regb) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_DEALLOC_OBJ_REGISTRY) fc None m' (seg_rom rsegs)
    /\ munch [(regb + 56, regb + 64); (P, P + 8)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ Registry LB m' regb (P + 384) 0 0
    /\ rw_cells rsegs m' P [C8 (wz allocb)].

Lemma fzH4 : forall gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P allocb regb schedb fst0 : Z) (LB : list block) (c8 : cell),
  Registry LB m regb (P + 384) fst0 0 -> regb + NEWSZ_REG <= hceil ->
  rw_cells rsegs m (P + 384) (IoCtxCells allocb regb schedb) ->
  rw_cells rsegs m P [c8] -> csize c8 = 8%nat ->
  hceil <= P -> P + 512 < 2^64 ->
  mem_inv rsegs m ->
  evt rsegs (fzH4_post gp tp (Z_to_bv 64 0) s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P allocb regb LB m)
    (MS (mkR (Z_to_bv 64 P_FZ_RET_DSV) (Z_to_bv 64 P) gp tp t0 t1 t2 (Z_to_bv 64 regb) (Z_to_bv 64 0) a0 a1 a2 a3 a4 a5 a6 a7
             s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
