Definition fz_ret_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (W : list (Z * Z)) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 0) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch W m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp).

Lemma fzI0 : forall gp tp t0 t1 t2 s0x s1x a0 a1 a2 a3 a4 a5 a6 a7 s2x s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P lo : Z) (ra s0 s1 s2 : word) (cs : list cell),
  rw_cells rsegs m (P + 408) (FlatBufCells FB_empty) ->
  rw_cells rsegs m (P + 480) [C8 s2; C8 s1; C8 s0; C8 ra] ->
  rw_cells rsegs m (P + 456) cs -> cells_size cs = 24%nat ->
  stk rsegs m lo (P + 408) -> hceil <= lo -> lo <= P -> P + 512 < 2^64 -> bv_unsigned ra mod 2 = 0 ->
  mem_inv rsegs m ->
  evt rsegs (fz_ret_post ra (Z_to_bv 64 (P + 512)) gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc [] lo m)
    (MS (mkR (Z_to_bv 64 P_FZ_RET_ADS) (Z_to_bv 64 P) gp tp t0 t1 t2 s0x s1x a0 a1 a2 a3 a4 a5 a6 a7
             s2x s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_FZ_RET_ADS) fc None m (seg_rom rsegs)).
